from storage.trace_query import query_many

def all_keys(obj, prefix=''):
    keys = set()
    if isinstance(obj, dict):
        for k, v in obj.items():
            keys.add(prefix + k)
            keys |= all_keys(v, prefix + k + '.')
    elif isinstance(obj, list):
        for v in obj:
            keys |= all_keys(v, prefix)
    return keys

